_startCryptoEncapsulation(headers) {
  const recipients = [
    this._compFields.to,
    this._compFields.cc,
    this._compFields.bcc,
    this._compFields.newsgroups,
  ]
    .filter(Boolean)
    .join(",");

  this._composeSecure.beginCryptoEncapsulation(
    this._fstream,
    recipients,
    this._compFields,
    headers,
    this._userIdentity,
    this._sendReport,
    this._deliverMode == Ci.nsIMsgSend.nsMsgSaveAsDraft
  );
  this._cryptoEncapsulationStarted = true;
}

/**
